// Audit the source-derived findings against independent, fixed arithmetic.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {createRequire} from 'node:module';
const require = createRequire(import.meta.url);
const {readClock, clock, raceRows, replayAt, forecast, trainingWindows} = require('../../assets/running-lab-analysis.js');
const half = JSON.parse(fs.readFileSync(new URL('../../assets/original/half-marathon-2025-2026-data.json', import.meta.url)));
const training = JSON.parse(fs.readFileSync(new URL('../../assets/original/sydney-2026-chart-data.json', import.meta.url)));
const original = JSON.stringify([half, training]);
const old = raceRows(half, '2025'), recent = raceRows(half, '2026');
assert.equal(old.length, 20); assert.equal(recent.length, 21);
assert.equal(replayAt(old, 19, 340).recorded, 7232);
assert.equal(replayAt(old, 19, 340).difference, 432);
assert.equal(replayAt(recent, 19, 340).recorded, 6284);
assert.equal(replayAt(recent, 20, 340).recorded, 6575);
assert.deepEqual(recent[20], {km:21, pace:291, heartRate:174, elevation:2});
assert.equal(old.slice(10,20).reduce((s,r)=>s+r.pace,0) - old.slice(0,10).reduce((s,r)=>s+r.pace,0), 368);
assert.equal(recent.slice(10,20).reduce((s,r)=>s+r.pace,0) - recent.slice(0,10).reduce((s,r)=>s+r.pace,0), -32);
assert.equal(readClock('1', '50', '57'), 6657);
for (const values of [['','',''], ['0','0','0'], ['1','60','0'], ['-1','0','0'], ['1','50.5','0'], ['1','50','60'], ['24','0','0']]) assert.equal(readClock(...values), null);
assert.equal(clock(forecast(6657, 1.06).projected), '3:51:19');
assert.equal(clock(forecast(6657, 1.10).projected), '3:57:50');
assert.equal(clock(forecast(6657, 1.10).margin, false), '2:10');
assert.equal(clock(forecast(6657, 1.06).requiredHalf), '1:55:07');
assert.equal(clock(forecast(6657, 1.10).requiredHalf), '1:51:58');
assert.equal(clock(forecast(6657, Math.log2(14400/6657)).projected), '4:00:00');
for (const values of [[null,1.06],[0,1.06],[6657,0.9],[6657,1.31],[6657,NaN],[Infinity,1.06]]) assert.equal(forecast(...values), null);
const windows = trainingWindows(training);
assert.equal(windows[0].count, 12);
assert.ok(Math.abs(windows[0].weeklyKm - 60.74166666666667) < 1e-10);
assert.equal(windows[1].start, 2); assert.equal(windows[1].weeklyKm, 73.325);
assert.equal(windows[2].weeklyKm, 64.7);
assert.equal(windows[3].weeklyKm, 83.9);
assert.equal(windows[3].first, '27 Jul');
assert.equal(JSON.stringify([half, training]), original, 'analysis never mutates the published record');
assert.throws(()=>raceRows({...half, 2025:{...half[2025],lap_average_hr_bpm:[]}}, '2025'));
assert.throws(()=>trainingWindows({...training,weekly_km:training.weekly_km.slice(1)}));
assert.throws(()=>replayAt(recent,21,340));
console.log('Running Lab: 41 full recorded laps, independent segment sums, prediction inversion, training-window selection and invalid-state boundaries passed.');
